package query

import "strconv"

// QuantifierColumnNames is how Java names the columns of a row read through a
// quantifier's flowed type (SemanticAnalyzer.resolveTableFunction's
// Expressions.fromQuantifier, a recursive CTE's union): a name stays only
// where it is unique (Expressions.underlyingAsColumns), and once any column
// lacks one, every unnamed or auto-generated (`_<digits>`) name becomes the
// column's position (Type.Record.normalizeFields). An empty label is unnamed.
func QuantifierColumnNames(labels []string) []string {
	counts := make(map[string]int, len(labels))
	for _, label := range labels {
		if label != "" {
			counts[label]++
		}
	}
	override := false
	for _, label := range labels {
		if label == "" || counts[label] > 1 {
			override = true
			break
		}
	}
	if !override {
		return labels
	}
	names := make([]string, len(labels))
	for i, label := range labels {
		if label == "" || counts[label] > 1 || isAutoGeneratedFieldName(label) {
			label = "_" + strconv.Itoa(i)
		}
		names[i] = label
	}
	return names
}

// isAutoGeneratedFieldName is Type.Record.Field.isAutoGenerated.
func isAutoGeneratedFieldName(name string) bool {
	if len(name) < 2 || name[0] != '_' {
		return false
	}
	for _, r := range name[1:] {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}
